import{_ as o,l,o as a,c as i,v as r,p as s,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"OpenCodeInterpreter","description":"","frontmatter":{"title":"OpenCodeInterpreter","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/opencodeinterpreter.md","filePath":"llm/opencodeinterpreter.md","lastUpdated":1789023840000}'),h={name:"llm/opencodeinterpreter.md"};function u(m,e,E,C,b,A){const n=l("Mermaid");return a(),i("div",null,[e[1]||(e[1]=r('<h1 id="opencodeinterpreter" tabindex="-1">OpenCodeInterpreter <a class="header-anchor" href="#opencodeinterpreter" aria-label="Permalink to &quot;OpenCodeInterpreter&quot;">​</a></h1><div class="epigraph"><p>把代码生成接到执行与多轮修正上：模型写出的程序经过解释器，反馈再写回对话，而不是单次采样碰 HumanEval。</p><footer>—— Zheng 等，OpenCodeInterpreter: Integrating Code Generation with Execution and Refinement，arXiv:2402.14658</footer></div><p>HumanEval 默认协议是一次生成、隐藏测试判分。真实写代码几乎总是：跑一下、看报错、改、再跑。Tianyu Zheng、Ge Zhang 等人 2024 年的 OpenCodeInterpreter（OCI，arXiv:2402.14658）把这条循环收成可训练的多轮分布：构造 <strong>Code-Feedback</strong> 对话数据，在 Code Llama / DeepSeek-Coder / CodeQwen 等代码基座上微调，使模型在看见解释器输出（以及可选的人类反馈）之后继续改代码。本篇写执行反馈如何进入后训练，以及评测一旦允许「跑测再改」，<code>pass@1</code> 的含义如何相对单次合成发生变化。不把仓库级修 issue 写成这篇的任务——那是 <a href="/llm/swe-agent">SWE-agent</a> 的 ACI 与 SWE-bench。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单次代码生成把编译错误、断言失败、超时全部折叠成「没过」。梯度或指令微调若从未见过「Traceback 下一轮该改哪」，模型只会在同一分布上再采样一次，等于用温度代替调试。闭源系统可以用内部执行循环抬分，开源线若只发布单轮 Instruct，用户在 IDE 里接解释器也接不上训练分布。OCI 要补的是：<strong>多轮轨迹</strong>公开、反馈类型可分（执行 vs 人类）、基座可换，从而证明「会修自己的代码」可以当作后训练目标，而不是产品黑盒。</p><p>另一问题是反馈泄漏。若训练里把隐藏测试的期望输出直接当观察，模型学会的是作弊读答案，不是读报错。合法观察应接近开发者能看见的东西：解释器 stdout/stderr、超时、语法错误，以及人类风格的「这里索引越界」——而不是测试套件的断言清单全文。论文用 Code-Feedback 把两类反馈写成对话轮次，就是要在数据层面把泄漏和调试分开。</p><h3 id="单轮-instruct-与带执行的多轮不是同一任务" tabindex="-1">单轮 Instruct 与带执行的多轮不是同一任务 <a class="header-anchor" href="#单轮-instruct-与带执行的多轮不是同一任务" aria-label="Permalink to &quot;单轮 Instruct 与带执行的多轮不是同一任务&quot;">​</a></h3><p>Base 或普通 Instruct 在 HumanEval 上的 pass@1，测的是单次合成。允许模型执行并迭代 \\(N\\) 轮后的 pass 率，测的是调试策略与反馈利用。两者都可以叫「HumanEval」，合同完全不同。OCI 的主表必须读清：是否开执行、轮数上限、是否另加人类反馈。把带执行的 80+% 拿去对 Code Llama 论文里的贪心单次 pass@1，是换题。</p><p><span class="marginnote">Code-Feedback 规模约 6.8 万条多轮。它不是 GitHub 原始 issue，而是围绕编程题构造的生成–执行–修正轨迹，并混入模拟或真实的人类意见。不要当成 SWE-bench 的开源版。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据：从编程任务出发，让模型（或教师）生成代码，送进沙箱执行，把返回拼成下一轮用户/系统观察，再生成修正；筛选留下最终能过测试或满足格式的轨迹。人类反馈轮提供自然语言指摘（缺边界、命名、复杂度），与编译器反馈互补——后者密、结构化，前者疏、针对「能跑但不好」。微调：在已有代码基座上做对话 SFT，模板必须区分「代码块」与「执行观察」，否则模型会在 Thought 里伪造 Traceback。</p><p>推理循环：生成 → 抽取代码 → 沙箱执行 → 观察写回 → 直到通过、达轮数上限或模型声明结束。沙箱约束（无网、限时、限内存）与 HumanEval 评测同一精神，见 <a href="/llm/code-bench">HumanEval / SWE-bench</a>。作者在多个尺寸上放出 OCI-CL、OCI-DS 等检查点，用来说明循环可迁移，不是绑死某一个基座。叙事上，带执行的 OCI 在 HumanEval / MBPP 及其 plus 变体上接近或局部超过当时的 GPT-4 单次/少轮数字——引用必须写「开执行的多轮」，不能写成「开源 33B 单次击败 GPT-4」。</p>',12)),(a(),s(c,null,{default:t(()=>[p(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E7%94%A8%E6%88%B7%E9%A2%98%E9%9D%A2%22%5D%20--%3E%20G%5B%22%E7%94%9F%E6%88%90%E4%BB%A3%E7%A0%81%22%5D%0A%20%20G%20--%3E%20X%5B%22%E6%B2%99%E7%AE%B1%E6%89%A7%E8%A1%8C%22%5D%0A%20%20X%20--%3E%20F%7B%22%E9%80%9A%E8%BF%87%3F%22%7D%0A%20%20F%20--%3E%7C%E6%98%AF%7C%20Y%5B%22%E6%8F%90%E4%BA%A4%22%5D%0A%20%20F%20--%3E%7C%E5%90%A6%7C%20O%5B%22%E8%A7%82%E5%AF%9F%EF%BC%9Astderr%20%2F%20%E8%B6%85%E6%97%B6%20%2F%20%E4%BA%BA%E7%B1%BB%E6%8C%87%E6%91%98%22%5D%0A%20%20O%20--%3E%20G%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h3 id="两种反馈进同一对话-梯度却不同质" tabindex="-1">两种反馈进同一对话，梯度却不同质 <a class="header-anchor" href="#两种反馈进同一对话-梯度却不同质" aria-label="Permalink to &quot;两种反馈进同一对话，梯度却不同质&quot;">​</a></h3><p>执行反馈是环境给的硬信号，几乎总是对的（沙箱本身除外）。人类反馈是软信号，可能错、可能过时。训练若把两种观察写成同一角色、同一前缀，模型会把「用户随便一说」当成编译器。方法上应在模板里标记来源，或至少在少样本里示范：对 Traceback 做针对性改行，对人类意见做设计层修改，不要每轮都整文件重写。论文强调 refinement，即局部修正优于推倒重来——这既省 token，也减少「越改越漂」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>执行观察把隐藏状态从「我猜测试会怎么查」拉到「类型错误在第 12 行」。下一轮的条件分布因此包含了单次生成没有的信息，pass 率上升在机制上几乎必然，真正要问的是：<strong>同样轮数预算下，SFT 过反馈的模型是否比未训练、只靠提示循环的基座更会改</strong>。OCI 的主张是会，因为轨迹教过「读哪一类错、改哪一块」。若只是在推理期套同一个循环而不微调，基座也会涨分，但浪费轮数、重复同一错误的比例更高。</p><h3 id="评测合同一松-执行循环就会刷爆单文件题" tabindex="-1">评测合同一松，执行循环就会刷爆单文件题 <a class="header-anchor" href="#评测合同一松-执行循环就会刷爆单文件题" aria-label="Permalink to &quot;评测合同一松，执行循环就会刷爆单文件题&quot;">​</a></h3><p>HumanEval 题短、依赖少、执行便宜，最适合展示 refinement。换到需要安装、网络、多文件的仓库，解释器反馈不再是一条 Traceback，而是构建系统噪声。OCI 不提供仓库定位工具，循环会在错误文件上反复执行。机制边界因此很清楚：这篇优化的是<strong>函数级调试对话</strong>，不是 issue 级软件工程。把 OCI 接上 grep/edit 而不改数据，等于把没见过的观察格式丢给模型。</p><p><span class="marginnote">plus 基准（更多测试、更狠边界）会让「一次碰巧过」变难，执行循环的相对收益往往更大。报分时写清 HumanEval 还是 HumanEval+，以及 \\(N\\) 轮。只写一个百分比无法复核。</span></p><p>沙箱必须由宿主执行。模型在文本里写「已运行，全部通过」不算观察。这与 <a href="/llm/react">ReAct</a> 里 Observation 不能由模型代写是同一条纪律。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><h3 id="泄漏、成本、与仓库代理的分工" tabindex="-1">泄漏、成本、与仓库代理的分工 <a class="header-anchor" href="#泄漏、成本、与仓库代理的分工" aria-label="Permalink to &quot;泄漏、成本、与仓库代理的分工&quot;">​</a></h3><p>训练或评测若把隐藏测试期望输出喂回去，分数无意义。每轮执行有 CPU 与超时成本，评测墙钟不再是生成 token 数。恶意代码（死循环、占盘）要靠沙箱，不在模型权重里解决；本篇不讨论越权利用，只强调默认无网、资源限额。OCI 不替代 <a href="/llm/aider">Aider</a> 或 Cursor 类工作流：那些要读仓库、打补丁、跑项目测试。它替代的是「单次 Instruct 写完函数」。</p><p>基座选择：代码预训练越强，第一轮代码越接近可跑，循环越短；弱基座会把预算耗在修语法。微调会损伤纯聊天，除非混入通用对话。许可随基座（Llama / DeepSeek / Qwen）走，Code-Feedback 数据许可另读仓库。</p><p><span class="marginnote">出处：Zheng et al.，<em>OpenCodeInterpreter: Integrating Code Generation with Execution and Refinement</em>，arXiv:2402.14658，2024。对照单次代码模型论文时，必须声明是否开执行循环。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OCI 把生成–执行–修正写成多轮 SFT 目标，数据为 Code-Feedback。</li><li>合法观察是解释器输出与人类指摘，不是隐藏测试答案。</li><li>带执行的 HumanEval 分与单次 pass@1 不可比。</li><li>任务单位是函数级调试，不是 SWE-bench 仓库修 bug。</li><li>出处：Zheng et al.，arXiv:2402.14658。</li></ul>',15))])}const I=o(h,[["render",u]]);export{f as __pageData,I as default};
